    /// * Path: `POST /docker.uploadFileToContainer`
    pub async fn docker_upload_file_to_container(
        &self,
        request: DockerUploadFileToContainerRequest,
    ) -> anyhow::Result<AiCreateResponse> {
        request.validate().context("parameter validation")?;
        let mut url = self.base_url.clone();
        url.path_segments_mut()
            .map_err(|()| anyhow::anyhow!("URL cannot be a base"))?
            .push("docker.uploadFileToContainer");
        let mut req_builder = self.client.post(url);
        let body = &request.body;
        let mut form = reqwest::multipart::Form::new();
        form = form.part(
            "container_id",
            reqwest::multipart::Part::text(body.container_id.to_string()),
        );
        form = form.part(
            "file",
            reqwest::multipart::Part::bytes(std::borrow::Cow::from(body.file.clone())),
        );
        form = form.part(
            "destination_path",
            reqwest::multipart::Part::text(body.destination_path.to_string()),
        );
        if let Some(val) = &body.server_id {
            form = form.part("server_id", reqwest::multipart::Part::text(val.to_string()));
        }
        req_builder = req_builder.multipart(form);
        let response = req_builder.send().await?;
        Ok(DockerUploadFileToContainerRequest::parse_response(response).await?)
    }
